'use strict';
let feedbackPending=false;
document.body.insertAdjacentHTML('beforeend','<dialog id="submission-feedback" aria-labelledby="feedback-title"><div id="feedback-body" role="status" aria-live="polite"></div><div id="feedback-actions" class="button-row"></div></dialog>');
const feedbackDelay=()=>new Promise(resolve=>setTimeout(resolve,1100)); // Visible synthetic Demo transition, not a real network delay.
function feedbackLock(on){$$('.sidebar button,#identity,#business').forEach(el=>{if(on){el.dataset.feedbackDisabled=String(el.disabled);el.disabled=true;}else{el.disabled=el.dataset.feedbackDisabled==='true';delete el.dataset.feedbackDisabled;}});}
function feedbackPanel(title,detail,kind='pending'){const spinner=kind==='pending'?'<span class="feedback-spinner" aria-hidden="true"></span>':'<span class="feedback-symbol" aria-hidden="true">'+(kind==='success'?'✓':'!')+'</span>';$('#feedback-body').innerHTML=spinner+'<h2 id="feedback-title">'+esc(title)+'</h2><p>'+esc(detail)+'</p><p class="muted">仅本地模拟流程，不代表真实接口、AI调用或生产审核。</p>';$('#submission-feedback').setAttribute('aria-busy',String(kind==='pending'));$('#feedback-actions').innerHTML='';if(!$('#submission-feedback').open)$('#submission-feedback').showModal();}
$('#submission-feedback').addEventListener('cancel',e=>{if(feedbackPending)e.preventDefault();});
function feedbackEnd(title,detail,success=true){feedbackPanel(title,detail,success?'success':'error');$('#feedback-actions').innerHTML='<button id="feedback-next" class="button primary">'+(success?'查看提交记录':'返回检查并重试')+'</button><button id="feedback-close" class="button ghost">'+(success?'完成':'关闭提示')+'</button>';$('#feedback-next').onclick=()=>{$('#submission-feedback').close();if(success)show('reviews');};$('#feedback-close').onclick=()=>$('#submission-feedback').close();}
async function feedbackCommit(action,successTitle,successDetail){if(feedbackPending)return;feedbackPending=true;feedbackLock(true);const confirms=$$('#effects-dialog button,#review-dialog [data-decision]');confirms.forEach(b=>b.disabled=true);feedbackPanel('正在提交','正在保存本地模拟记录，请勿重复提交。');try{await feedbackDelay();const before=JSON.stringify(db.reviews);action();const error=$('#effects-dialog')?.open?$('#effects-error')?.textContent:'';if(error||JSON.stringify(db.reviews)===before){feedbackEnd('尚未提交',error||'没有产生新的提交记录，请检查当前状态。',false);return;}if(!persist()){feedbackEnd('本地保存失败','未确认提交完成。请保留当前内容或下载备份，检查浏览器存储空间后重试；不要将本次状态当作已可靠保存。',false);return;}feedbackEnd(successTitle,successDetail);}catch(e){feedbackEnd('提交未完成','内容保留，请检查后重试。'+e.message,false);}finally{feedbackPending=false;feedbackLock(false);confirms.forEach(b=>b.disabled=false);}}
const feedbackEffects=effectDialog;
effectDialog=function(r){feedbackEffects(r);$('#effects-save').textContent=admin()?'确认无误，纳入团队参考':'确认无误，提交审核';const original=$('#effects-save').onclick;$('#effects-save').onclick=()=>{const e={quality:$('#effect-quality').checked,viral:$('#effect-viral').checked,platform:$('#effect-platform').value,confirmed:$('#effect-confirm').checked,sales:$('#effect-sales').value};const error=F.validateEffects(e);if(error){$('#effects-error').textContent=error;return;}const direct=admin();feedbackCommit(original,direct?'已纳入团队参考':'提交成功，等待审核',direct?'管理员确认已记录，当前版本已纳入本地团队模拟参考。可查看记录，后续仍可撤销。':'当前文案版本和效果声明已提交。尚未审核通过，不会因提交而直接供团队参考。');};};
const feedbackReview=openReview;
openReview=function(x){feedbackReview(x);$$('#review-dialog [data-decision]').forEach(b=>{const original=b.onclick,decision=b.dataset.decision;b.onclick=()=>feedbackCommit(original,({approved:'审核完成，已纳入团队参考',rejected:'处理完成，已退回',revoked:'处理完成，已撤销参考'})[decision],({approved:'审核结果已保存，批准的文案快照可供后续模拟检索。',rejected:'退回结果已保存，未纳入团队参考。',revoked:'撤销结果已保存，后续任务不再使用该参考；历史记录保留。'})[decision]);});};
const feedbackTaskRun=run;
run=async function(input,parent=null){if(busy||feedbackPending)return;let timer;try{const promise=feedbackTaskRun(input,parent);const live=$('#result-page .live-status');if(live){live.setAttribute('role','status');live.setAttribute('aria-live','polite');live.setAttribute('aria-busy','true');live.insertAdjacentHTML('afterbegin','<span class="feedback-spinner" aria-hidden="true"></span>');live.insertAdjacentHTML('beforeend','<p id="task-progress-step">正在准备本次模拟处理…</p>');let step=0;timer=setInterval(()=>{const p=$('#task-progress-step');if(p)p.textContent=['正在检索合成参考…','正在整理模拟结果与来源…','正在保存本地记录…'][Math.min(step++,2)];},180);}await promise;const page=$('#result-page');if(page.querySelector('.result-top')){const saved=persist();page.querySelector('.result-top').insertAdjacentHTML('afterend','<div id="task-terminal" class="feedback-terminal '+(saved?'':'feedback-error')+'" role="status">'+(saved?'处理完成，结果已保存到本地历史。可继续修改、下载或查看历史。':'处理已结束，但本地保存失败。请先下载备份，不要直接刷新页面。')+'</div>');}else if(!page.querySelector('.live-status')){page.insertAdjacentHTML('beforeend','<p class="feedback-terminal feedback-error" role="status">本次处理已结束，未生成成功成稿。请按上方提示调整后重试。</p>');}}catch(e){busy=false;$('#submit').disabled=false;show('result');$('#result-page').innerHTML='<div class="notice blocked"><h1>处理未完成</h1><p>输入已保留，请返回检查后重试。</p><button id="task-error-return" class="button primary">返回原输入</button></div>';$('#task-error-return').onclick=()=>show('creator');}finally{clearInterval(timer);}};
const feedbackLockedTaskRun=run;
run=async function(...args){if(busy||feedbackPending)return;feedbackLock(true);try{return await feedbackLockedTaskRun(...args);}finally{feedbackLock(false);}};
